{"implementation":"def solve(case):
    segments = case["segments"]
    budget = case["budget"]
    n = len(segments)
    allocations = [min(segment["minimum"], segment["capacity"]) for segment in segments]
    remaining = budget - sum(allocations)

    if remaining > 0:
        while remaining > 0:
            eligible = [i for i, segment in enumerate(segments) if allocations[i] < segment["capacity"]]
            if not eligible:
                break
            weight_total = sum(max(0, segments[i]["importance"]) for i in eligible)
            if weight_total <= 0:
                for i in eligible:
                    if remaining <= 0:
                        break
                    allocations[i] += 1
                    remaining -= 1
                continue

            shares = []
            assigned = 0
            for i in eligible:
                room = segments[i]["capacity"] - allocations[i]
                share = remaining * max(0, segments[i]["importance"]) / weight_total
                amount = min(room, int(share))
                allocations[i] += amount
                assigned += amount
                shares.append((share - int(share), segments[i]["importance"], -i, i))
            remaining -= assigned

            if remaining > 0:
                shares.sort(reverse=True)
                progressed = False
                for _, _, _, i in shares:
                    if remaining <= 0:
                        break
                    if allocations[i] < segments[i]["capacity"]:
                        allocations[i] += 1
                        remaining -= 1
                        progressed = True
                if not progressed:
                    break

    by_name = {segment["name"]: allocations[i] for i, segment in enumerate(segments)}
    return {"allocations": allocations, "by_name": by_name, "total": sum(allocations)}"}
